<?php
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/functions.php';require_role(['admin']);
$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$role=$_POST['role']??'security';$password=$_POST['password']??'';
if($name&&filter_var($email,FILTER_VALIDATE_EMAIL)&&strlen($password)>=8&&in_array($role,['admin','security'],true)){
$hash=password_hash($password,PASSWORD_DEFAULT);try{$s=$conn->prepare("INSERT INTO users(name,email,password,role) VALUES(?,?,?,?)");$s->bind_param('ssss',$name,$email,$hash,$role);$s->execute();flash('Staff account created.');redirect('employees.php');}catch(mysqli_sql_exception $e){$msg='Email already exists or account could not be created.';}
}else $msg='Check the details. Password must be at least 8 characters.';}
$res=$conn->query("SELECT id,name,email,role,status,created_at FROM users ORDER BY created_at DESC");
$pageTitle='Staff Management';require '../includes/header.php';?><div class="layout"><?php require '../includes/admin_nav.php';?><section class="content"><h1>Staff accounts</h1><?php if($msg):?><div class="alert danger"><?=e($msg)?></div><?php endif;?><div class="form-card"><h2>Add staff / security officer</h2><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div><label>Full name</label><input name="name" required></div><div><label>Email</label><input type="email" name="email" required></div><div><label>Temporary password</label><input type="password" name="password" minlength="8" required></div><div><label>Role</label><select name="role"><option value="security">Security officer</option><option value="admin">Administrator</option></select></div><div class="span2"><button class="btn">Create account</button></div></form></div><div class="table-wrap"><table><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th></tr><?php while($u=$res->fetch_assoc()):?><tr><td><?=e($u['name'])?></td><td><?=e($u['email'])?></td><td><?=e($u['role'])?></td><td><?=e($u['status'])?></td></tr><?php endwhile;?></table></div></section></div><?php require '../includes/footer.php';?>
